class SafeUnpickler(pickle.Unpickler):
    """
    A restricted Unpickler that only allows safe built-in types.
    This prevents arbitrary code execution when deserializing untrusted legacy data.
    """
    SAFE_TYPES = {
        'dict', 'list', 'set', 'str', 'int', 'float', 'bool', 'tuple', 'bytes'
    }

    def find_class(self, module, name):
        if module in ('builtins', '__builtin__') and name in self.SAFE_TYPES:
